def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]

    if denominator == 0:
        return None

    value = numerator / denominator

    return {
        "value": value,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
